
/* jsPDF AutoTable offline stub */
(function() {
  if (typeof jsPDF === 'undefined') return;

  jsPDF.prototype.autoTable = function(opts) {
    const head = opts.head || [];
    const body = opts.body || [];
    const startY = opts.startY || 20;
    const headStyles = opts.headStyles || {};
    const theme = opts.theme || 'grid';

    // Build HTML table
    let tableHtml = '<table>';
    if (head.length) {
      tableHtml += '<thead><tr>';
      head[0].forEach(h => {
        const bg = headStyles.fillColor ? `background:rgb(${headStyles.fillColor.join(',')})` : '';
        tableHtml += `<th style="${bg};color:${headStyles.textColor?'white':'#000'}">${h}</th>`;
      });
      tableHtml += '</tr></thead>';
    }
    tableHtml += '<tbody>';
    body.forEach((row, ri) => {
      tableHtml += `<tr>`;
      row.forEach(cell => {
        tableHtml += `<td>${cell !== null && cell !== undefined ? cell : '–'}</td>`;
      });
      tableHtml += '</tr>';
    });
    tableHtml += '</tbody></table>';

    // Store for later rendering
    if (!this._tableHtml) this._tableHtml = '';
    this._tableHtml += tableHtml;

    // Update finalY estimate
    const rowH = 7; // mm per row
    this.lastAutoTable = { finalY: startY + (head.length + body.length) * rowH };

    // Override _buildPDFContent to include tables
    const self = this;
    this._buildPDFContent = function() {
      let html = '<div class="page">';
      for (const el of self._elements) {
        if (el.type === 'text') {
          const isTitle = el.fontSize >= 13;
          const isSection = el.fontSize >= 11;
          if (isTitle) html += `<h2 style="color:${el.color}">${el.text}</h2>`;
          else if (isSection) html += `<h3 style="color:${el.color}">${el.text}</h3>`;
          else html += `<p style="color:${el.color}">${el.text.replace(/\n/g,'<br>')}</p>`;
        }
      }
      if (self._tableHtml) html += self._tableHtml;
      html += '</div>';
      return html;
    };

    return this;
  };
})();
